DO $$
DECLARE
  using_expr text;
BEGIN
  -- Pick the ownership path that matches the actual schema:
  -- 1) orders.user_id is the auth user, or
  -- 2) orders.customer_id -> customers.id, and customers.user_id is the auth user.
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'user_id'
  ) THEN
    using_expr := 'user_id = auth.uid()';
  ELSIF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'customer_id'
  ) AND EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'customers' AND column_name = 'user_id'
  ) THEN
    using_expr := 'customer_id IN (SELECT c.id FROM public.customers c WHERE c.user_id = auth.uid())';
  ELSE
    RAISE EXCEPTION 'Cannot determine the ownership path for public.orders; no changes were made.';
  END IF;

  ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;

  DROP POLICY IF EXISTS orders_select_own ON public.orders;

  EXECUTE format(
    'CREATE POLICY orders_select_own ON public.orders FOR SELECT TO authenticated USING (%s)',
    using_expr
  );
END $$;
