-- Finds foreign keys with no covering btree index and adds one.
-- Safety: if the number of unindexed FKs is not exactly 1, the whole block
-- raises an exception and the transaction rolls back (no changes made).
DO $$
DECLARE
  r record;
  cols text;
  n int := 0;
BEGIN
  FOR r IN
    SELECT c.oid AS con_oid, c.conname, c.conrelid, c.conkey
    FROM pg_constraint c
    WHERE c.contype = 'f'
      AND NOT EXISTS (
        SELECT 1
        FROM pg_index i
        WHERE i.indrelid = c.conrelid
          AND i.indpred IS NULL                       -- ignore partial indexes
          AND i.indnatts >= cardinality(c.conkey)
          AND NOT EXISTS (                            -- index leading columns must match FK columns in order
            SELECT 1
            FROM unnest(c.conkey) WITH ORDINALITY AS k(attnum, pos)
            WHERE i.indkey[pos - 1] IS DISTINCT FROM k.attnum
          )
      )
  LOOP
    n := n + 1;

    SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY k.pos)
      INTO cols
    FROM unnest(r.conkey) WITH ORDINALITY AS k(attnum, pos)
    JOIN pg_attribute a ON a.attrelid = r.conrelid AND a.attnum = k.attnum;

    EXECUTE format('CREATE INDEX %I ON %s (%s)',
                   'idx_' || r.conname, r.conrelid::regclass, cols);
    RAISE NOTICE 'Created index idx_% on % (%)', r.conname, r.conrelid::regclass, cols;
  END LOOP;

  IF n <> 1 THEN
    RAISE EXCEPTION 'Expected exactly one unindexed foreign key, found %. No changes made.', n;
  END IF;
END
$$;
